using System.Globalization;
using System.IO;
using System.Runtime.InteropServices;
using System.Xml.Linq;
namespace MRS;
internal static class FoxHuntTests
{
 internal static string Nmea(string text){byte sum=0;foreach(char c in text)sum^=(byte)c;return "$"+text+"*"+sum.ToString("X2");}
 internal static FoxScope Scope=>new("Synthetic fixed-gain receiver","RTL",146520000,"NFM",12500,200,960000,146520000,900000,0,0);
 internal static void Run(Action<bool,string> check)
 {
  var now=DateTimeOffset.UtcNow;var parser=new FoxNmea();parser.Feed("$GPGGA,123519,4807.038,N,01131.000,E,1,08,0.9,545.4,M,46.9,M,,*47",now,"Synthetic NMEA");check(parser.Fix!=null&&Math.Abs(parser.Fix.Latitude-48.1173)<1e-6&&Math.Abs(parser.Fix.Longitude-11.5166667)<1e-6,"Fox GPS decodes independently checksummed GGA coordinates");check(parser.Fix!.Satellites==8&&parser.Fix.Hdop==.9&&parser.Fix.Altitude==545.4,"Fox GPS retains satellites, HDOP and altitude");parser.Feed("$GPRMC,123519,A,4807.038,N,01131.000,E,022.4,084.4,230394,003.1,W*6A",now,"Synthetic NMEA");check(parser.Fix?.SpeedKnots==22.4&&parser.Fix.Course==84.4&&parser.Fix.GpsUtc?.Year==1994,"Fox RMC UTC date/speed/course are distinct from receive time");check(parser.Fix!.Fresh(now)&&!parser.Fix.Fresh(now.AddSeconds(4)),"Fox GPS fix expires after three seconds without fresh position");parser.Feed(Nmea("GNRMC,123520,A,4000.000,S,10000.000,W,1,2,011126,,,A"),now,"Synthetic NMEA");check(parser.Fix?.Latitude==-40&&parser.Fix.Longitude==-100,"Fox accepts multi-GNSS talker and southern/western hemispheres");parser.Feed(Nmea("GNRMC,123521,V,,,,,,,011126,,,N"),now,"Synthetic NMEA");check(parser.Fix==null,"Valid-checksum no-fix RMC immediately invalidates the previous position");parser.Feed(Nmea("GPGGA,123519,4867.038,N,01131.000,E,1,08,0.9,545.4,M,46.9,M,,"),now,"Synthetic NMEA");check(parser.Fix==null,"Fox rejects coordinates with invalid minutes");parser.Feed(Nmea("GPGGA,123519,4807.038,N,01131.000,E,0,00,0.9,545.4,M,46.9,M,,"),now,"Synthetic NMEA");check(parser.Fix==null,"Fox rejects GGA zero-quality fix");parser.Feed(Nmea("GPRMC,123519,A,4807.038,N,01131.000,E,1,2,011126,,,S"),now,"Synthetic NMEA");check(parser.Fix==null,"Simulator NMEA cannot become a live GPS fix");parser.Feed(Nmea("GPGGA,123519,4807.038,N,01131.000,E,6,08,0.9,545.4,M,46.9,M,,"),now,"Synthetic NMEA");check(parser.Fix==null,"Dead-reckoned-only GGA is not treated as a current GPS position");parser.Feed("$GPRMC,123519,A,4807.038,N,01131.000,E,1,2,011126,,,A*00",now,"Synthetic NMEA");check(parser.Fix==null&&parser.BadChecksum==1,"Fox drops bad NMEA checksum");check(Math.Abs(FoxNmea.Distance(0,0,0,1)-111195)<20,"Fox geodesic separation has expected distance");
  var dcb=typeof(FoxGps).GetNestedType("Dcb",System.Reflection.BindingFlags.NonPublic)!;check(Marshal.SizeOf(dcb)==28,"Windows GPS DCB interop layout is exactly 28 bytes");
  var window=new FoxSignalWindow();window.Add(new(now,Scope,-60,false));window.Add(new(now,Scope,double.NaN,true));check(window.Recent(now,1).Length==1,"Fox RF window drops invalid powers");check(window.Recent(now.AddSeconds(4),1).Length==0,"Fox RF data cannot silently remain fresh after source stops");for(int i=0;i<5000;i++)window.Add(new(now,Scope,-50,true));check(window.Recent(now,1).Length==4096,"Fox RF queue stays bounded");
  string root=Path.Combine(Path.GetTempPath(),"MRS-Fox-Synthetic-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);string csv=Path.Combine(root,"route.csv"),gpx=Path.Combine(root,"route.gpx"),auto=Path.Combine(root,"auto.csv");using var session=new FoxSession();var fix=new FoxFix(40,-100,now,"Synthetic NMEA");bool Reject(Action f){try{f();return false;}catch{return true;}}
  try{
   check(Reject(()=>session.Start(auto,Scope with{Gain=-1000},fix))&&!File.Exists(auto),"Fox blocks automatic RTL RF gain before creating a log");session.Start(csv,Scope,fix);check(session.Record(now,null,new[]{new FoxReading(now,Scope,-40,true)})==null,"Fox never records a location without a fix");check(session.Record(now,fix,Array.Empty<FoxReading>())==null,"Fox never invents RF power for a GPS-only observation");check(session.Record(now.AddSeconds(5),fix,new[]{new FoxReading(now.AddSeconds(5),Scope,-40,true)})==null,"Fox pauses points on stale GPS rather than reusing old position");var readings=new[]{new FoxReading(now,Scope,-60,false),new FoxReading(now,Scope,-40,true)};var first=session.Record(now,fix,readings,-70)!;check(Math.Abs(first.MeanDb-(-42.967086))<.001&&first.PeakDb==-40,"Fox averages RF power in linear units and retains peak separately");check(first.Readings==2&&first.FloorDb==-70&&first.Segment==1,"Fox retains sample count, noise evidence and route segment");check(Reject(()=>session.Record(now,fix,new[]{new FoxReading(now,Scope with{Gain=300},-30,true)}))&&session.Points.Count==1,"Gain changes cannot contaminate the current comparable session");check(Reject(()=>session.Record(now,fix with{Source="Different GPS"},readings)),"Position-source changes cannot silently mix into a session");var second=session.Record(now.AddSeconds(1),fix with{ReceivedUtc=now.AddSeconds(1)},readings.Select(r=>r with{Utc=now.AddSeconds(1)}).ToArray(),signalOnly:true)!;check(second.MeanDb==-40&&second.Readings==1,"Signal-only logging excludes closed-squelch power readings");var later=now.AddSeconds(15);var third=session.Record(later,fix with{ReceivedUtc=later,Latitude=40.001},new[]{new FoxReading(later,Scope,-35,true)})!;check(third.Segment==2,"Fox starts a new route segment after a long measurement gap");FoxSession.ExportGpx(gpx,session.Points);var xml=XDocument.Load(gpx);XNamespace ns="http://www.topografix.com/GPX/1/1";check(xml.Descendants(ns+"trkpt").Count()==3&&xml.Descendants(ns+"trkseg").Count()==2,"GPX export preserves measured points and discontinuous segments");session.Dispose();var parsed=PlanCsv.Read(csv);check(parsed.Count==3&&parsed[0]["frequency_hz"]=="146520000"&&parsed[0]["mean_db_relative"].StartsWith("-42.967"),"Fox CSV flushes each row with invariant RF/channel metadata");check(Reject(()=>session.Start(csv,Scope,fix)),"Fox will not overwrite an existing log");check(FoxMap.SignalColor(-100,-100,-30).B==255&&FoxMap.SignalColor(-30,-100,-30).R==255,"Fox map colors distinguish relative weaker/stronger measurements");
  }finally{session.Dispose();foreach(string file in new[]{csv,gpx,auto})if(File.Exists(file))File.Delete(file);Directory.Delete(root);}
 }
}
